INSERT INTO findings (id, finding_id, aws_account_id, assessment_id, control_id, title, description, category, severity, resource_type, resource_id, region, evidence, business_risk, recommendation, owner_id, status, due_date, created_at) VALUES
  ('00000000-0000-0000-0001-000000000001', 'F-1001', '00000000-0000-0000-0000-000000000100', '00000000-0000-0000-0000-000000000a07', (SELECT id FROM controls WHERE control_id = 'DR-002'), 'Production RDS backup restore has not been validated', 'The primary production RDS instance has no record of a validated restore test in the last 90 days. Backups are being taken but recovery has never been verified.', 'Backup', 'CRITICAL', 'RDS', 'db-prod-orders-01', 'us-east-1', 'AWS Backup vault shows daily snapshots for db-prod-orders-01. No restore job found in the last 90 days. Last successful restore test: none on record.', 'In the event of a data corruption or regional outage, the recovery procedure is unproven and may fail, leading to extended downtime and potential data loss for the orders service.', 'Schedule and execute a full restore test into an isolated VPC, validate application integrity, and document the RTO/RPO. Establish a quarterly restore-test cadence.', '00000000-0000-0000-0000-000000000011', 'IN_PROGRESS', '2026-08-26', '2026-08-12T08:00:00Z'),
  ('00000000-0000-0000-0001-000000000002', 'F-1002', '00000000-0000-0000-0000-000000000100', '00000000-0000-0000-0000-000000000a04', (SELECT id FROM controls WHERE control_id = 'SEC-002'), 'S3 bucket allows public read access to customer data', 'An S3 bucket containing customer export data has a bucket policy allowing public read access to all objects.', 'S3', 'CRITICAL', 'S3', 's3-prod-customer-exports', 'us-east-1', 'Bucket policy statement: {"Effect":"Allow","Principal":"*","Action":"s3:GetObject","Resource":"arn:aws:s3:::s3-prod-customer-exports/*"}. Public access block settings are not enabled at the account level.', 'Sensitive customer data is exposed to the public internet, creating a compliance violation under GDPR and CCPA and a significant data breach risk.', 'Immediately remove the public read policy statement, enable S3 Block Public Access at the account and bucket level, and audit all objects for prior unauthorized access via CloudTrail.', '00000000-0000-0000-0000-000000000013', 'INVESTIGATING', '2026-08-22', '2026-08-14T12:30:00Z'),
  ('00000000-0000-0000-0001-000000000003', 'F-1003', '00000000-0000-0000-0000-000000000100', '00000000-0000-0000-0000-000000000a01', (SELECT id FROM controls WHERE control_id = 'EKS-001'), 'Production EKS control plane running unsupported Kubernetes version', 'The production EKS cluster control plane is running Kubernetes 1.24 which is past end-of-support and no longer receives security patches.', 'EKS', 'CRITICAL', 'EKS', 'eks-prod-main', 'us-east-1', 'Cluster version: 1.24.17. EKS supported versions: 1.27, 1.28, 1.29, 1.30. Cluster was last upgraded 14 months ago.', 'Running an unsupported Kubernetes version means no security patches for critical CVEs, potential incompatibility with managed add-ons, and loss of AWS support eligibility.', 'Plan a controlled upgrade to 1.29 following the EKS upgrade documentation. Run the upgrade in a maintenance window with rollback procedures documented.', '00000000-0000-0000-0000-000000000012', 'PLANNED', '2026-09-02', '2026-08-10T09:00:00Z'),
  ('00000000-0000-0000-0001-000000000004', 'F-1004', '00000000-0000-0000-0000-000000000100', '00000000-0000-0000-0000-000000000a02', (SELECT id FROM controls WHERE control_id = 'SEC-003'), 'CloudTrail logging disabled in us-west-2 region', 'CloudTrail trail is not logging events in the us-west-2 region, creating a blind spot for security auditing and incident response.', 'Security', 'CRITICAL', 'CloudTrail', 'CloudTrail (us-west-2)', 'us-west-2', 'Trail "management-events" has isMultiRegionTrail=true but logging was disabled for us-west-2 on 2026-07-30. Last log event from us-west-2: 2026-07-30T14:22Z.', 'Without complete CloudTrail coverage, security incidents in us-west-2 cannot be investigated, and compliance requirements for audit logging are not met.', 'Re-enable CloudTrail logging for us-west-2 immediately. Add a CloudWatch alarm to alert on logging disablement. Review who made the change via IAM.', '00000000-0000-0000-0000-000000000013', 'OPEN', '2026-08-21', '2026-08-15T16:00:00Z')
INSERT INTO findings (id, finding_id, aws_account_id, assessment_id, control_id, title, description, category, severity, resource_type, resource_id, region, evidence, business_risk, recommendation, owner_id, status, due_date, created_at) VALUES
  ('00000000-0000-0000-0001-000000000005', 'F-1005', '00000000-0000-0000-0000-000000000100', '00000000-0000-0000-0000-000000000a01', (SELECT id FROM controls WHERE control_id = 'EKS-002'), 'EKS add-on versions are inconsistent across environments', 'EKS add-ons (vpc-cni, kube-proxy, coredns) are running different versions across production, development, and test clusters, leading to inconsistent behavior and deployment risk.', 'EKS', 'HIGH', 'EKS', 'eks-prod-main / eks-dev-main / eks-test-main', 'us-east-1', 'vpc-cni: prod=v1.12.0, dev=v1.11.3, test=v1.12.0. kube-proxy: prod=v1.24.7, dev=v1.24.7, test=v1.25.3. coredns: all environments differ.', 'Inconsistent add-on versions make it difficult to reproduce issues across environments and increase the risk of production failures that cannot be caught in lower environments.', 'Standardize add-on versions across all clusters. Use GitOps to manage add-on configuration and enforce version parity via CI checks.', '00000000-0000-0000-0000-000000000012', 'IN_PROGRESS', '2026-09-05', '2026-08-08T10:00:00Z'),
  ('00000000-0000-0000-0001-000000000006', 'F-1006', '00000000-0000-0000-0000-000000000100', '00000000-0000-0000-0000-000000000a02', (SELECT id FROM controls WHERE control_id = 'SEC-001'), 'Security group allows unrestricted SSH access', 'Security group permits inbound SSH access from 0.0.0.0/0.', 'Security', 'HIGH', 'EC2', 'sg-prod-web-01', 'us-east-1', 'Inbound rule: port 22, source 0.0.0.0/0, protocol TCP. Security group is attached to 4 EC2 instances in the production web tier.', 'Internet-exposed SSH increases the attack surface and may allow unauthorized access attempts, brute-force attacks, and potential compromise of production web servers.', 'Restrict SSH access to approved administrative networks or use AWS Systems Manager Session Manager for secure, audited access without open inbound ports.', '00000000-0000-0000-0000-000000000013', 'OPEN', '2026-09-15', '2026-08-05T08:00:00Z'),
  ('00000000-0000-0000-0001-000000000007', 'F-1007', '00000000-0000-0000-0000-000000000100', '00000000-0000-0000-0000-000000000a06', (SELECT id FROM controls WHERE control_id = 'OBS-002'), 'Several critical workloads have insufficient observability', 'Three critical microservices lack distributed tracing, custom metrics, and alerting dashboards, making it difficult to detect and diagnose production issues.', 'Observability', 'HIGH', 'Lambda', 'orders-api, payments-api, inventory-svc', 'us-east-1', 'orders-api: no X-Ray tracing, no custom CloudWatch alarms. payments-api: no dashboard, no SLO defined. inventory-svc: logs present but no metrics.', 'Without proper observability, production incidents take longer to diagnose, increasing MTTR and potentially extending customer-facing outages.', 'Instrument all three services with OpenTelemetry, define SLOs and error-rate alerts, and create service-level dashboards in CloudWatch or Grafana.', '00000000-0000-0000-0000-000000000011', 'IN_PROGRESS', '2026-09-10', '2026-08-06T11:00:00Z'),
  ('00000000-0000-0000-0001-000000000008', 'F-1008', '00000000-0000-0000-0000-000000000100', '00000000-0000-0000-0000-000000000a03', (SELECT id FROM controls WHERE control_id = 'IAM-001'), 'IAM role with wildcard permissions attached to EC2 instances', 'An EC2 instance role has an attached policy with Action:* and Resource:*, violating least-privilege principles.', 'IAM', 'HIGH', 'IAM', 'iam-role-ec2-prod-legacy', 'us-east-1', 'Policy "LegacyFullAccess" attached to role "iam-role-ec2-prod-legacy". Policy document: {"Action":"*","Resource":"*"}. Role attached to 2 EC2 instances.', 'If any of these instances are compromised, the attacker gains full access to all AWS services in the account, potentially leading to data exfiltration or infrastructure destruction.', 'Replace the wildcard policy with a scoped-down policy granting only the permissions the application requires. Use IAM Access Analyzer to identify actual usage.', '00000000-0000-0000-0000-000000000013', 'INVESTIGATING', '2026-09-01', '2026-08-09T14:00:00Z'),
  ('00000000-0000-0000-0001-000000000009', 'F-1009', '00000000-0000-0000-0000-000000000100', '00000000-0000-0000-0000-000000000a05', (SELECT id FROM controls WHERE control_id = 'NET-001'), 'VPC Flow Logs not enabled for production VPC', 'VPC Flow Logs are not enabled for the primary production VPC, preventing network traffic auditing and security investigation.', 'Networking', 'HIGH', 'VPC', 'vpc-prod-main', 'us-east-1', 'VPC vpc-prod-main (vpc-0abc123) has no flow log configurations. VPC contains 6 subnets across 2 AZs hosting production workloads.', 'Without flow logs, network-based attacks, misconfigurations, and unauthorized traffic cannot be investigated, hindering incident response and compliance.', 'Enable VPC Flow Logs to a dedicated S3 bucket with appropriate retention. Configure log format to include all fields for security analysis.', '00000000-0000-0000-0000-000000000012', 'OPEN', '2026-09-08', '2026-08-07T09:30:00Z'),
  ('00000000-0000-0000-0001-000000000010', 'F-1010', '00000000-0000-0000-0000-000000000100', '00000000-0000-0000-0000-000000000a07', (SELECT id FROM controls WHERE control_id = 'DR-001'), 'Production RDS instance has no automated backup plan', 'A production RDS instance handling payments has no AWS Backup plan configured, relying only on default automated backups with no cross-region copy.', 'Backup', 'HIGH', 'RDS', 'db-prod-payments-02', 'us-east-1', 'RDS instance db-prod-payments-02: BackupRetentionPeriod=7 (default), no AWS Backup plan assigned, no cross-region snapshot copy configured.', 'Loss of the payments database without a proper backup plan could result in permanent data loss and inability to process transactions.', 'Enroll the instance in an AWS Backup plan with daily snapshots, 30-day retention, and cross-region copy to the DR region.', '00000000-0000-0000-0000-000000000011', 'IN_PROGRESS', '2026-08-28', '2026-08-11T13:00:00Z'),
  ('00000000-0000-0000-0001-000000000011', 'F-1011', '00000000-0000-0000-0000-000000000200', '00000000-0000-0000-0000-000000000a10', (SELECT id FROM controls WHERE control_id = 'IAM-002'), 'Unused IAM role with excessive permissions detected', 'An IAM role has not been used in 180 days but retains administrator-level permissions.', 'IAM', 'HIGH', 'IAM', 'iam-role-dev-deprecated-service', 'us-east-1', 'Role "iam-role-dev-deprecated-service" last used: 2026-02-15. Attached policy: AdministratorAccess. No trust policy updates in 6 months.', 'Dormant roles with high privileges are prime targets for privilege escalation attacks if credentials are leaked or compromised.', 'Remove the role if no longer needed. If still required, reduce permissions to least-privilege and document the business justification.', '00000000-0000-0000-0000-000000000012', 'OPEN', '2026-09-12', '2026-08-04T10:00:00Z'),
  ('00000000-0000-0000-0001-000000000012', 'F-1012', '00000000-0000-0000-0000-000000000200', '00000000-0000-0000-0000-000000000a09', (SELECT id FROM controls WHERE control_id = 'EKS-003'), 'EKS node group running deprecated AMI type', 'An EKS managed node group is running on a deprecated Amazon Linux 2 AMI that no longer receives security updates.', 'EKS', 'HIGH', 'EKS', 'eks-dev-main / nodegroup-dev-1', 'us-east-1', 'Node group nodegroup-dev-1: AMI type AL2_x86_64, release version 1.24.17-20240301. Amazon Linux 2 EOL: 2025-06-30.', 'Nodes running deprecated AMIs are vulnerable to known security issues and may become incompatible with future EKS versions.', 'Upgrade the node group to Amazon Linux 2023 or Bottlerocket. Use a rolling update strategy to minimize disruption.', '00000000-0000-0000-0000-000000000012', 'PLANNED', '2026-09-15', '2026-08-03T11:00:00Z'),
  ('00000000-0000-0000-0001-000000000013', 'F-1013', '00000000-0000-0000-0000-000000000100', '00000000-0000-0000-0000-000000000a08', (SELECT id FROM controls WHERE control_id = 'GOV-001'), 'Production workload lacks required resource tags', 'Multiple production resources are missing required tags (owner, environment, cost-center, data-classification), preventing cost allocation and governance.', 'Governance', 'HIGH', 'EC2', '14 EC2 instances, 3 RDS instances, 7 S3 buckets', 'us-east-1', '24 resources missing "owner" tag, 18 missing "cost-center", 14 missing "data-classification". Tag compliance: 61%.', 'Without proper tagging, cost allocation is inaccurate, ownership is unclear, and automated governance policies cannot be enforced.', 'Apply required tags to all resources. Implement tag policies via AWS Organizations and use auto-tagging Lambda for new resources.', '00000000-0000-0000-0000-000000000011', 'IN_PROGRESS', '2026-09-20', '2026-08-02T08:00:00Z'),
  ('00000000-0000-0000-0001-000000000014', 'F-1014', '00000000-0000-0000-0000-000000000100', '00000000-0000-0000-0000-000000000a06', (SELECT id FROM controls WHERE control_id = 'OBS-001'), 'CloudWatch log group has no retention policy', 'A high-volume CloudWatch log group has no retention policy set, causing unbounded log storage growth and cost.', 'Observability', 'HIGH', 'CloudWatch', '/aws/lambda/prod-order-processor', 'us-east-1', 'Log group /aws/lambda/prod-order-processor: retention=Never (NeverExpire). Storage: 847 GB and growing. Monthly cost: $423.', 'Unbounded log retention leads to escalating costs and makes log analysis slower and more expensive over time.', 'Set a 90-day retention policy. Archive logs older than 90 days to S3 with Glacier transition for long-term compliance retention.', '00000000-0000-0000-0000-000000000011', 'OPEN', '2026-09-06', '2026-08-06T15:00:00Z'),
  ('00000000-0000-0000-0001-000000000015', 'F-1015', '00000000-0000-0000-0000-000000000100', '00000000-0000-0000-0000-000000000a05', (SELECT id FROM controls WHERE control_id = 'NET-002'), 'Transit Gateway has no flow logs enabled', 'The production Transit Gateway routing traffic between VPCs and on-premises has no flow logs enabled.', 'Networking', 'HIGH', 'Transit Gateway', 'tgw-prod-main', 'us-east-1', 'TGW tgw-prod-main: 0 flow log configurations. TGW has 6 attachments (4 VPC, 2 VPN).', 'Inter-VPC and hybrid network traffic cannot be audited, making it difficult to diagnose routing issues or detect suspicious cross-network access.', 'Enable Transit Gateway Flow Logs to a dedicated S3 bucket with 1-year retention for network audit and security analysis.', '00000000-0000-0000-0000-000000000012', 'OPEN', '2026-09-11', '2026-08-05T09:00:00Z'),
  ('00000000-0000-0000-0001-000000000016', 'F-1016', '00000000-0000-0000-0000-000000000200', '00000000-0000-0000-0000-000000000a09', (SELECT id FROM controls WHERE control_id = 'EKS-004'), 'EKS cluster has no pod-level resource requests configured', 'Multiple deployments in the development EKS cluster have no CPU or memory resource requests defined, leading to scheduling instability.', 'EKS', 'HIGH', 'EKS', 'eks-dev-main / 23 deployments', 'us-east-1', '23 of 67 deployments have no resource requests. 41 deployments have no resource limits. Cluster shows frequent pod evictions due to memory pressure.', 'Without resource requests, the scheduler cannot make informed placement decisions, leading to node starvation and unpredictable pod evictions.', 'Define resource requests and limits for all workloads. Use Vertical Pod Autoscaler in recommendation mode to right-size based on actual usage.', '00000000-0000-0000-0000-000000000012', 'PLANNED', '2026-09-18', '2026-08-01T10:00:00Z')
